/* Public office identity and curated demo fixtures. Internal verification data is never rendered here. */
const OFFICE_DEMOS={
 'demo-central':{id:'demo-central',name:'Хотын Өргөө',agent:'Жишээ зөвлөх · Төв оффис',headline:'Хотын амьдралд таны орон зайг олъё.',description:'Гэрэл сайтай жижиг байрнаас гэр бүлийн орон сууц хүртэл — таны хэрэгцээнд тохирох сонголтыг нэг дороос. Энэ нь сэтгэгдэл, баталгаа эсвэл бодит байгууллагын мэдээлэл биш, интерфэйсийн жишээ юм.',address:'Улаанбаатар · Сүхбаатар · Жишээ оффисын байршил',businessHours:'Даваа–Баасан 09:00–18:00 · Жишээ',latitude:47.9189,longitude:106.917,logo:'assets/oroo.png',coverIndex:1,demo:true},
 'demo-west':{id:'demo-west',name:'Тавтай Орон Зай',agent:'Жишээ зөвлөх · Баруун оффис',headline:'Шинэ эхлэлд тань тохирох байр.',description:'Түрээс болон худалдах орон сууцны сонголтуудыг хараарай. Энэ профайл болон холбоотой зарууд нь зөвхөн загварын жишээ мэдээлэл юм.',address:'Улаанбаатар · Баянгол · Жишээ оффисын байршил',businessHours:'Даваа–Бямба 10:00–18:00 · Жишээ',latitude:47.918,longitude:106.864,logo:'assets/oroo.png',coverIndex:3,demo:true}
};
const OFFICE_DEMO_LINKS=Object.fromEntries(Array.from({length:24},(_,i)=>[59377690+i,{officeId:i%2===0?'demo-central':'demo-west',agentId:i%2===0?'demo-agent-central':'demo-agent-west'}]));
const OFFICE_PROFILE_FIELDS=['headline','description','businessHours','showPhone','showEmail','latitude','longitude','logo','portrait','cover'];
const officePhotoKeys=new Map();
let officeFilters={},officeReturnListing=null,officeMap=null,officeMapObserver=null,officePhotoBusy=false;
PRO_MENU.splice(PRO_MENU.findIndex(m=>m[0]==='settings'),0,['office','briefcase','Нийтийн профайл']);
function officeProfileState(){const p=proState();if(!p.publicOfficeProfile||typeof p.publicOfficeProfile!=='object')p.publicOfficeProfile={draft:{headline:'',description:'',businessHours:'',showPhone:false,showEmail:false,latitude:'',longitude:'',logo:'',portrait:'',cover:''},revision:0};p.publicOfficeProfile.draft=officeCleanDraft(p.publicOfficeProfile.draft||{});return p.publicOfficeProfile}
function officeIdentity(h){if(!h)return null;if(h.local||h.proManaged||h.brokerId||h.officeId){const id=h.officeId||adminBrokerId(h);return id?{officeId:id,agentId:h.agentId||(id==='broker-local'?'agent-local':'')}:null}return OFFICE_DEMO_LINKS[h.id]||null}
function officeBindListing(h){const id=adminBrokerId(h);if(id){h.officeId=id;h.brokerId=id;h.agentId=h.agentId||(id==='broker-local'?'agent-local':'')}return h}
function officeCleanDraft(d={}){return Object.fromEntries(OFFICE_PROFILE_FIELDS.map(k=>[k,['showPhone','showEmail'].includes(k)?!!d[k]:String(d[k]??'').trim()]))}
function officePhotoKey(value){if(officePhotoKeys.has(value))return officePhotoKeys.get(value);let a=2166136261,b=5381;for(let i=0;i<value.length;i++){a=Math.imul(a^value.charCodeAt(i),16777619);b=Math.imul(b,33)^value.charCodeAt(i)}const key=[value.length,a>>>0,b>>>0].join(':');if(officePhotoKeys.size>=6)officePhotoKeys.delete(officePhotoKeys.keys().next().value);officePhotoKeys.set(value,key);return key}
function officeProfileKey(draft=officeProfileState().draft){const d=officeCleanDraft(draft);return JSON.stringify([brokerKey(),...OFFICE_PROFILE_FIELDS.map(k=>[k,['logo','portrait','cover'].includes(k)?officePhotoKey(d[k]):d[k]])])}
function officePublicModel(id){if(Object.prototype.hasOwnProperty.call(OFFICE_DEMOS,id))return {...OFFICE_DEMOS[id]};if(id!=='broker-local'||!brokerEligible(id))return null;const profile=officeProfileState(),review=adminState().officeProfileReview;if(!review||!review.snapshot||review.status!=='approved'||review.key!==officeProfileKey()||profile.submittedKey!==review.key)return null;const p=proState().office,s=review.snapshot;return {id,name:p.name,agent:p.agent,address:p.address,registration:p.registration,licenseNumber:p.licenseNumber,validUntil:adminState().brokerReviews[id]?.final?.validUntil,phone:s.showPhone?p.phone:'',email:s.showEmail?p.email:'',headline:s.headline,description:s.description,businessHours:s.businessHours,latitude:s.latitude===''?null:Number(s.latitude),longitude:s.longitude===''?null:Number(s.longitude),logo:s.logo,portrait:s.portrait,cover:s.cover,demo:false,reviewedAt:review.date}}
function officeAsset(value){return typeof value==='string'&&/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(value)?value:''}
function officeCover(model){return model.demo?img(model.coverIndex,1500):officeAsset(model.cover)}
function officeAvatar(model,person=false){const src=person?officeAsset(model.portrait):model.demo?model.logo:officeAsset(model.logo);return src?`<img src="${src}" alt="${person?'Зуучлагчийн зураг':'Байгууллагын лого'}">`:`<span aria-hidden="true">${person?icon('user'):icon('briefcase')}</span>`}
function officeBadge(model){return model.demo?'<span class="office-trust is-demo">'+icon('image')+'Жишээ байгууллага</span>':brokerVerificationBadge(model.id)}
function officePublicHomes(id){if(!officePublicModel(id))return [];return homes.filter(h=>officeIdentity(h)?.officeId===id&&isPublicListing(h))}
function officeRelatedHomes(h){const identity=officeIdentity(h);return identity?officePublicHomes(identity.officeId).filter(item=>item.id!==h.id):homes.filter(item=>item.id!==h.id&&isPublicListing(item)&&!officeIdentity(item)&&item.local&&h.local&&h.contactName&&item.contactName===h.contactName)}
function officeListingCard(h){const identity=officeIdentity(h);if(!identity)return `<div class="office-owner-card"><div>${icon('user')}<b>${h.contactRole==='owner'?'Өмчлөгчийн мэдээлэл':'Зар оруулагчийн мэдээлэл'}</b></div>${listingContactRows(h)}</div>`;const model=officePublicModel(identity.officeId);if(!model)return brokerVerificationBadge(identity.officeId)+'<div class="office-unavailable-card">'+icon('shield')+'Байгууллагын нийтэд харагдах профайл одоогоор нээлтгүй.</div>'+listingContactRows(h);const count=officePublicHomes(model.id).length;return `<article class="office-detail-card"><a class="office-detail-title" href="#/offices/${model.id}" onclick="officeReturnListing=${h.id};officeResetFilters('${model.id}')"><div class="office-avatar">${officeAvatar(model)}</div><div><b>${esc(model.name)}</b>${officeBadge(model)}</div>${icon('chevron-right')}</a><div class="office-card-agent"><i>${officeAvatar(model,true)}</i><span>${esc(model.agent||'Холбоо барих ажилтан оруулаагүй')}</span></div><dl><div><dt>Хаяг</dt><dd>${esc(model.address||'Оруулаагүй')}</dd></div><div><dt>Ажлын цаг</dt><dd>${esc(model.businessHours||'Оруулаагүй')}</dd></div>${model.phone?'<div><dt>Утас</dt><dd>'+esc(model.phone)+'</dd></div>':''}</dl><a class="office-detail-all" href="#/offices/${model.id}" onclick="officeReturnListing=${h.id};officeResetFilters('${model.id}')"><span>Байгууллагын бүх зар <b>${count}</b></span>${icon('arrow-right')}</a><div class="office-card-actions"><button type="button" ${model.phone?'':'disabled'} onclick="officeContact('${model.id}','phone',${h.id})">${icon('phone')}Утас</button><button class="primary" onclick="officeContact('${model.id}','message',${h.id})">${icon('message')}Лавлагаа</button></div>${model.demo?'<p class="office-card-note">Загварын жишээ · Бодит байгууллагын баталгаа биш</p>':''}</article>`}
function officeRelatedLink(h){const id=officeIdentity(h)?.officeId;return id&&officePublicModel(id)?`<a class="office-related-all" href="#/offices/${id}" onclick="officeReturnListing=${h.id}">Байгууллагын бүх зарыг харах ${icon('arrow-right')}</a>`:''}
function officeResetFilters(id){officeFilters[id]={q:'',type:'all',deal:'all',rooms:'all',sort:'new',page:0}}
function officeFilter(id){if(!officeFilters[id])officeResetFilters(id);return officeFilters[id]}
function officeFilteredHomes(id){const f=officeFilter(id),q=f.q.toLowerCase();let list=officePublicHomes(id).filter(h=>(!q||[h.name,h.area,h.desc,String(h.id)].join(' ').toLowerCase().includes(q))&&(f.type==='all'||h.type===Number(f.type))&&(f.deal==='all'||h.deal===f.deal)&&(f.rooms==='all'||(f.rooms==='5+'?Number(h.rooms)>=5:String(h.rooms)===f.rooms)));if(f.sort==='price')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));else if(f.sort==='price-desc')list.sort((a,b)=>(b.price??-1)-(a.price??-1));else if(f.sort==='size')list.sort((a,b)=>b.size-a.size);else list.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))||b.id-a.id);return list}
function officeApplyFilters(event,id){event.preventDefault();const f=new FormData(event.target);officeFilters[id]={q:String(f.get('q')||'').trim(),type:String(f.get('type')||'all'),deal:String(f.get('deal')||'all'),rooms:String(f.get('rooms')||'all'),sort:String(f.get('sort')||'new'),page:0};render();document.getElementById('office-listings')?.scrollIntoView({block:'start'})}
function officeChooseFilter(id,key,value){if(!['type','deal','rooms','sort'].includes(key))return;const input=document.querySelector('.office-list-search input');if(typeof input?.value==='string')officeFilter(id).q=input.value.trim();officeFilter(id)[key]=value;officeFilter(id).page=0;render()}
function officePage(id){const m=officePublicModel(id);if(!id)return officeDirectory();if(!m)return `<div class="wrap office-page office-missing">${emptyFlow('Байгууллагын профайл нээлтгүй','Профайл нийтлэгдээгүй, хяналтад байгаа эсвэл нийтэд харагдах эрх нь дууссан байж болно.','<a href="#/offices"><button>Байгууллагуудыг харах</button></a>')}</div>`;const list=officeFilteredHomes(id),f=officeFilter(id),total=officePublicHomes(id).length;f.page=Math.max(0,Math.min(f.page,Math.max(0,Math.ceil(list.length/8)-1)));const cover=officeCover(m),returnId=officeReturnListing&&homes.some(h=>h.id===officeReturnListing&&isPublicListing(h))?officeReturnListing:null;return `<div class="wrap office-page"><div class="office-breadcrumb"><a href="${returnId?'#/room/'+returnId:'#/offices'}">${icon('arrow-left')}${returnId?'Зар руу буцах':'Зуучлалын байгууллагууд'}</a><button onclick="officeShare('${id}')" aria-label="Байгууллагын холбоос хуваалцах">${icon('share')}Хуваалцах</button></div><section class="office-public-hero ${cover?'with-cover':''}">${cover?`<div class="office-cover"><img src="${cover}" alt="Байгууллагын танилцуулгын зураг"><span>${m.demo?'Загварын жишээ':'Байгууллагын танилцуулга'}</span></div>`:''}<div class="office-hero-body"><div class="office-hero-identity"><div class="office-avatar office-avatar-large">${officeAvatar(m)}</div><div>${officeBadge(m)}<h1>${esc(m.name)}</h1><p>${esc(m.headline||'Таны орон зайг хамтдаа олъё.')}</p></div></div><div class="office-hero-actions"><button ${m.phone?'':'disabled'} onclick="officeContact('${id}','phone')">${icon('phone')}Утсаар холбогдох</button><button class="primary" onclick="officeContact('${id}')">${icon('message')}Лавлагаа илгээх</button></div></div><div class="office-introduction"><p>${esc(m.description||'Байгууллагын танилцуулга хараахан оруулаагүй.')}</p><div class="office-agent-label"><i>${officeAvatar(m,true)}</i><span>${esc(m.agent||'Зуучлагчийн нэр оруулаагүй')}</span></div></div></section><div class="office-section-links"><a href="#office-information" onclick="event.preventDefault();document.getElementById('office-information').scrollIntoView({behavior:'smooth'})">Үндсэн мэдээлэл</a><a href="#office-location" onclick="event.preventDefault();document.getElementById('office-location').scrollIntoView({behavior:'smooth'})">Байршил</a><a href="#office-listings" onclick="event.preventDefault();document.getElementById('office-listings').scrollIntoView({behavior:'smooth'})">Нийт зар <b>${total}</b></a></div><div class="office-info-layout"><section class="office-information" id="office-information"><div class="office-section-title"><h2>Үндсэн мэдээлэл</h2>${icon('briefcase')}</div><dl>${[['Төлөөлөгч',m.agent],['Холбоо барих утас',m.phone],['Имэйл',m.email],['Улсын бүртгэл',m.demo?'Жишээ профайл':m.registration],['Зуучлалын зөвшөөрөл',m.demo?'Бодит зөвшөөрөл биш':m.licenseNumber],['Ажлын цаг',m.businessHours],['Платформын хяналт',m.demo?'Жишээ · Баталгаажуулалт биш':m.validUntil?'Хүчинтэй: '+m.validUntil:'—'],['Хаяг',m.address]].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'Нийтэд оруулаагүй')}</dd></div>`).join('')}</dl></section><section class="office-location" id="office-location"><div class="office-section-title"><h2>Байршил</h2>${icon('pin')}</div>${officeHasCoordinates(m)?`<div id="office-map" aria-label="${esc(m.name)} байршил"></div><p class="office-map-status" role="status">Газрын зураг ачаалж байна…</p><div class="office-map-caption"><span>${m.demo?'Жишээ оффисын цэг':'Байгууллагын оруулсан байршил'}</span><button onclick="officeOpenMapsMe('${id}')">MAPS.ME ${icon('external-link')}</button></div>`:'<div class="office-no-map">'+icon('pin')+'<p>Баталгаажуулах координат оруулаагүй.</p></div>'}</section></div><section id="office-listings" class="office-listings"><div class="office-list-head"><div><span>БАЙГУУЛЛАГЫН ЗАРУУД</span><h2>Таны дараагийн орон зай <b>${total}</b></h2></div><p>Зөвхөн нийтэд харагдах зарууд</p></div><form class="office-list-filters" onsubmit="officeApplyFilters(event,'${id}')"><label class="office-list-search">${icon('search')}<input name="q" aria-label="Байгууллагын зар хайх" placeholder="Нэр, дүүрэг, зарын дугаар" value="${esc(f.q)}"></label>${officeSelect('Зарын төрөл','type',[['all','Бүх төрөл'],...types.map((t,i)=>[String(i),t])],f.type,id)}${officeSelect('Гэрээний төрөл','deal',[['all','Түрээс / Худалдах'],['rent','Түрээс'],['sale','Худалдах']],f.deal,id)}${officeSelect('Өрөөний тоо','rooms',[['all','Бүх өрөө'],...['1','2','3','4','5+'].map(n=>[n,n+' өрөө']),['shared','Хамтран амьдрах']],f.rooms,id)}${officeSelect('Зарын эрэмбэ','sort',[['new','Шинэ нь эхэнд'],['price','Үнэ өсөхөөр'],['price-desc','Үнэ буурахаар'],['size','Талбай буурахаар']],f.sort,id)}<button class="primary">Хайх</button></form><div class="office-results-meta"><span>${list.length} зар олдлоо</span><button onclick="officeResetFilters('${id}');render()">Шүүлтүүр цэвэрлэх</button></div><div class="cards office-property-grid">${list.slice(f.page*8,f.page*8+8).map(card).join('')}</div>${!list.length?emptyFlow('Тохирох зар олдсонгүй','Шүүлтүүр эсвэл хайлтаа өөрчилнө үү.'):''}${officePagination(id,list.length)}</section><div class="office-public-disclosure">${icon('shield')}<p>${m.demo?'Энэ байгууллага, зураг болон зарууд нь интерфэйсийн жишээ. Бодит зуучлагчийн үнэлгээ, зөвшөөрлийн баталгаа биш.':'Профайл нь платформын демо хяналтын мэдээлэл. Бодит байгууллагын эрх, гүйлгээний баталгаа биш.'}</p></div></div>`}
function officeSelect(label,key,options,value,id){return `<label class="office-list-select"><span>${label}</span><select name="${key}" aria-label="${label}" onchange="officeChooseFilter('${id}','${key}',this.value)">${options.map(([k,t])=>`<option value="${k}" ${value===k?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function officePagination(id,count){const f=officeFilter(id),pages=Math.ceil(count/8);return pages>1?`<div class="office-pagination"><button aria-label="Өмнөх зарын хуудас" ${f.page===0?'disabled':''} onclick="officeFilter('${id}').page--;render();document.getElementById('office-listings').scrollIntoView()">${icon('chevron-left')}</button>${Array.from({length:pages},(_,i)=>`<button ${f.page===i?'aria-current="page"':''} onclick="officeFilter('${id}').page=${i};render();document.getElementById('office-listings').scrollIntoView()">${i+1}</button>`).join('')}<button aria-label="Дараах зарын хуудас" ${f.page===pages-1?'disabled':''} onclick="officeFilter('${id}').page++;render();document.getElementById('office-listings').scrollIntoView()">${icon('chevron-right')}</button></div>`:''}
function officeDirectory(){const ids=[...Object.keys(OFFICE_DEMOS),...(officePublicModel('broker-local')?['broker-local']:[])];return `<div class="wrap office-directory"><span class="eyebrow">ӨРӨӨ · ЗУУЧЛАЛЫН БАЙГУУЛЛАГУУД</span><h1>Таны орон зайд хөтлөх хүмүүс.</h1><p>Байгууллагын танилцуулга болон нийтэд харагдах зарууд.</p><div>${ids.map(id=>{const m=officePublicModel(id);return `<a href="#/offices/${id}" onclick="officeReturnListing=null;officeResetFilters('${id}')"><div class="office-avatar">${officeAvatar(m)}</div><div>${officeBadge(m)}<h2>${esc(m.name)}</h2><p>${esc(m.headline)}</p><span>${officePublicHomes(id).length} нийтэд харагдах зар</span></div>${icon('arrow-right')}</a>`}).join('')}</div></div>`}
function officeHasCoordinates(m){return m.latitude!==null&&m.longitude!==null&&m.latitude!==''&&m.longitude!==''&&Number.isFinite(Number(m.latitude))&&Number.isFinite(Number(m.longitude))}
function destroyOfficeMap(){officeMapObserver?.disconnect();officeMapObserver=null;officeMap?.remove();officeMap=null}
function mountOfficePage(id){const m=officePublicModel(id),host=document.getElementById('office-map');if(!m||!host||!officeHasCoordinates(m))return;const status=document.querySelector('.office-map-status'),fail=()=>{if(status){status.hidden=false;status.textContent='Газрын зургийг ачаалж чадсангүй. Доорх холбоосоор байршлыг нээнэ үү.'}};if(typeof maplibregl==='undefined'){fail();return}try{officeMap=new maplibregl.Map({container:host,style:'https://tiles.openfreemap.org/styles/liberty',center:[Number(m.longitude),Number(m.latitude)],zoom:14,minZoom:3,maxZoom:18,attributionControl:true});new maplibregl.Marker({color:'#ff385c'}).setLngLat([Number(m.longitude),Number(m.latitude)]).addTo(officeMap);officeMap.on('load',()=>{if(status)status.hidden=true});officeMap.on('error',fail);if(typeof ResizeObserver!=='undefined'){officeMapObserver=new ResizeObserver(()=>officeMap?.resize());officeMapObserver.observe(host)}}catch{fail()}}
function officeOpenMapsMe(id){const m=officePublicModel(id);if(!m||!officeHasCoordinates(m))return;modal(`<h2>${esc(m.name)}</h2><p>${esc(m.address)}</p><p class="notice">${m.demo?'Жишээ оффисын байршил':'Байгууллагын оруулсан координат'}</p><a class="mapsme-open-link" href="${esc(mapsMeUrl(Number(m.latitude),Number(m.longitude),m.name))}">MAPS.ME нээх ${icon('external-link')}</a>`)}
function officeShare(id){const url=(location.href?.split('#')[0]||location.origin+location.pathname)+'#/offices/'+id;modal(`<h2>Байгууллагын холбоос</h2><label class="field">Хуулах холбоос<input readonly value="${esc(url)}" onclick="this.select()"></label><p class="notice">Локал демо холбоос · Нийтэд байршуулсны дараа бусад төхөөрөмжөөс нээнэ.</p>`)}
function officeContact(id,kind='message',listingId){const m=officePublicModel(id);if(!m||kind==='phone'&&!m.phone)return;const list=officePublicHomes(id);if(listingId&&!list.some(h=>h.id===Number(listingId)))return;modal(`<div class="office-inquiry-head"><div class="office-avatar">${officeAvatar(m)}</div><div>${officeBadge(m)}<h2>${esc(m.name)}</h2><p>${esc(m.agent||'')}</p></div></div>${kind==='phone'&&m.phone?'<p class="office-contact-number">'+esc(m.phone)+'</p>':''}<p class="notice">Браузерт хадгалах демо лавлагаа · Бодит мессеж, дуудлага илгээгдэхгүй.</p><form onsubmit="officeSubmitContact(event,'${id}','${kind}')"><label class="field">Холбоотой зар<select name="listingId" aria-label="Холбоотой зар"><option value="">Байгууллагын ерөнхий лавлагаа</option>${list.map(h=>`<option value="${h.id}" ${h.id===Number(listingId)?'selected':''}>№ ${h.id} · ${esc(h.name)}</option>`).join('')}</select></label><label class="field">Асуулт<textarea name="body" required maxlength="1000" placeholder="Хайж буй байр, төсөв, үзлэгийн цагаа бичээрэй."></textarea></label><p class="office-form-error" role="alert"></p><div class="flow-actions"><button type="button" onclick="closeOverlay()">Буцах</button><button class="primary">Лавлагаа хадгалах</button></div></form>`);document.querySelector('.modal').classList.add('office-contact-modal')}
function officeSubmitContact(event,id,kind){event.preventDefault();if(!['message','phone'].includes(kind)||!officePublicModel(id))return;const f=new FormData(event.target),raw=String(f.get('listingId')||''),listingId=raw?Number(raw):null,body=String(f.get('body')||'').trim();if(!body||body.length>1000||raw&&(!Number.isFinite(listingId)||!officePublicHomes(id).some(h=>h.id===listingId))){event.target.querySelector('.office-form-error').textContent='Лавлагаа болон холбоотой зараа шалгана уу.';return}const m=officePublicModel(id),record={id:flowId(),kind,officeId:id,agentId:listingId?officeIdentity(homes.find(h=>h.id===listingId))?.agentId:id==='broker-local'?'agent-local':'',propertyId:listingId||undefined,title:listingId?'Зар № '+listingId:m.name+' · Байгууллагын лавлагаа',body,date:flowDate(),status:'Орон нутгийн демо'};flowState.requests.unshift(record);if(!persistFlows()){flowState.requests.shift();return}closeOverlay();toast('Лавлагаа хадгалагдлаа · Миний булангаас үзнэ үү.')}
function officeInquiryTitle(r){return r.propertyId?proListingName(r.propertyId):r.officeId==='broker-local'?proState().office.name:'Байгууллагын лавлагаа'}
function officeProfileErrors(d){const errors=[];if(!d.headline||d.headline.length>100)errors.push('100 хүртэл тэмдэгттэй товч танилцуулга оруулна уу.');if(!d.description||d.description.length>1500)errors.push('1500 хүртэл тэмдэгттэй танилцуулга оруулна уу.');if(!d.businessHours||d.businessHours.length>100)errors.push('Ажлын цагаа оруулна уу.');const hasLat=d.latitude!=='',hasLng=d.longitude!=='';if(hasLat!==hasLng||hasLat&&(!Number.isFinite(Number(d.latitude))||!Number.isFinite(Number(d.longitude))||Number(d.latitude)<-90||Number(d.latitude)>90||Number(d.longitude)<-180||Number(d.longitude)>180))errors.push('Өргөрөг, уртрагыг зөв хосоор оруулна уу.');for(const key of ['logo','portrait','cover'])if(d[key]&&!officeAsset(d[key]))errors.push('Зургийн мэдээлэл буруу байна.');return errors}
function proOfficePage(){const profile=officeProfileState(),d=profile.draft,r=adminState().officeProfileReview,status=officePublicModel('broker-local')?'published':profile.submittedKey===officeProfileKey()&&r?.key===profile.submittedKey?r.status:profile.submittedKey===officeProfileKey()?'pending':'draft';return `${proHeading('ХЭРЭГЛЭГЧИД ХАРАГДАХ ПРОФАЙЛ','Байгууллагын нийтийн профайл','Байгууллагын танилцуулга, зураг, байршил ба холбоо барих мэдээлэл.')}<div class="office-editor-layout"><section class="pro-panel"><div class="pro-panel-head"><h2>Профайлын мэдээлэл</h2>${adminBadge(status)}</div><p class="pro-note">Нэр, төлөөлөгч, хаяг, зөвшөөрлийг байгууллагын баталгаажуулсан мэдээллээс авна. Үндсэн мэдээллийг Байгууллагын мэдээлэл хэсэгт засна.</p><form id="office-profile-form" onsubmit="officeSaveProfile(event)"><label class="office-edit-field">Товч танилцуулга<input name="headline" maxlength="100" value="${esc(d.headline||'')}" placeholder="Таны байгууллагын онцлогийг товч бичээрэй."></label><label class="office-edit-field">Байгууллагын тухай<textarea name="description" rows="5" maxlength="1500">${esc(d.description||'')}</textarea></label><label class="office-edit-field">Ажлын цаг<input name="businessHours" maxlength="100" value="${esc(d.businessHours||'')}" placeholder="Даваа–Баасан 09:00–18:00"></label><div class="office-profile-photos">${[['logo','Лого'],['portrait','Төлөөлөгчийн зураг'],['cover','Танилцуулгын зураг']].map(([key,label])=>`<div><b>${label}</b><div class="office-photo-preview" id="office-photo-${key}">${officeAsset(d[key])?'<img src="'+d[key]+'" alt="'+label+'">':icon(key==='portrait'?'user':'image')}</div><label class="office-upload-button">${icon('image')}Зураг сонгох<input type="file" accept="image/jpeg,image/png" aria-label="${label} оруулах" onchange="officeReadPhoto(this,'${key}')"></label><button type="button" onclick="officeRemovePhoto('${key}')">Хасах</button></div>`).join('')}</div><p class="office-photo-status" role="status">JPEG / PNG · Зураг тус бүр 8 MB хүртэл · Браузерт багасгаж хадгална.</p><div class="office-edit-coordinates"><label class="office-edit-field">Оффисын өргөрөг<input name="latitude" type="number" step="any" min="-90" max="90" value="${esc(d.latitude||'')}" placeholder="47.9189"></label><label class="office-edit-field">Оффисын уртраг<input name="longitude" type="number" step="any" min="-180" max="180" value="${esc(d.longitude||'')}" placeholder="106.9170"></label></div><p class="pro-note">Зөвхөн оффисын бодит координатыг оруулна. Байрны координат эсвэл дүүргийн төвөөр автоматаар нөхөхгүй.</p><label class="office-profile-check"><input name="showPhone" type="checkbox" ${d.showPhone?'checked':''}>Баталгаажуулсан байгууллагын утсыг нийтэд харуулах (${esc(proState().office.phone||'утас оруулаагүй')})</label><label class="office-profile-check"><input name="showEmail" type="checkbox" ${d.showEmail?'checked':''}>Байгууллагын имэйлийг нийтэд харуулах</label><p class="office-form-error" role="alert"></p><div class="office-editor-actions"><button name="action" value="draft">${icon('bookmark')}Түр хадгалах</button><button class="primary" name="action" value="submit">${icon('shield')}Профайл хяналтад илгээх</button></div></form></section><aside class="pro-panel office-editor-guide"><span>ПРОФАЙЛЫН ХАРАГДАЦ</span><div class="office-avatar office-avatar-large">${officeAvatar({logo:d.logo})}</div><h2>${esc(proState().office.name)}</h2><p>${esc(d.headline||'Таны товч танилцуулга энд харагдана.')}</p><ol><li>Мэдээлэл, зураг, координатаа хадгалах</li><li>Байгууллагын хоёр шатны хяналтыг дуусгах</li><li>Нийтийн профайлаа админд шалгуулах</li><li>Нийтэд харагдах зараас профайл руу холбогдох</li></ol>${r?.reason?'<p class="office-review-feedback">Админы тайлбар: '+esc(r.reason)+'</p>':''}${officePublicModel('broker-local')?'<a class="office-preview-link" href="#/offices/broker-local">Нийтийн профайлыг нээх '+icon('arrow-up-right')+'</a>':'<p class="pro-note">Батлаагүй эсвэл өөрчлөгдсөн профайл нийтэд харагдахгүй.</p>'}<a href="#/offices/demo-central">Жишээ профайл харах ${icon('arrow-up-right')}</a></aside></div>`}
function officeCaptureForm(form){const f=new FormData(form),old=officeProfileState().draft;return officeCleanDraft({...old,headline:f.get('headline'),description:f.get('description'),businessHours:f.get('businessHours'),latitude:f.get('latitude'),longitude:f.get('longitude'),showPhone:f.has('showPhone'),showEmail:f.has('showEmail')})}
function officeSaveProfile(event){event.preventDefault();if(officePhotoBusy)return;const d=officeCaptureForm(event.target),submit=event.submitter?.value==='submit',errors=submit?officeProfileErrors(d):[];if(submit&&!brokerEligible())errors.push('Байгууллагын хоёр шатны хяналтыг эхлээд дуусгана уу.');if(errors.length){event.target.querySelector('.office-form-error').textContent=errors.join(' ');return}const before=JSON.stringify(proState());const state=officeProfileState();state.draft=d;if(submit){state.revision=Number(state.revision||0)+1;state.submittedKey=officeProfileKey(d);state.submittedAt=new Date().toISOString()}if(!persistFlows()){flowState.pro=JSON.parse(before);return}render();toast(submit?'Профайл админы хяналтад орлоо.':'Нийтийн профайлын ноорог хадгалагдлаа.')}
async function officeReadPhoto(input,key){const file=input.files?.[0];if(officePhotoBusy){input.value='';return}if(!file||!['logo','portrait','cover'].includes(key))return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>8*1024*1024){toast('JPEG / PNG зураг, 8 MB хүртэл.');input.value='';return}const form=document.getElementById('office-profile-form'),status=document.querySelector('.office-photo-status');officePhotoBusy=true;if(status)status.textContent='Зураг боловсруулж байна…';try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)}),photo=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>{try{const max=key==='cover'?1400:480,scale=Math.min(1,max/Math.max(picture.width,picture.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(picture.width*scale));canvas.height=Math.max(1,Math.round(picture.height*scale));const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(picture,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))}catch(e){reject(e)}};picture.onerror=reject;picture.src=data});const before=JSON.stringify(proState());officeProfileState().draft={...officeCaptureForm(form),[key]:photo};if(!persistFlows()){flowState.pro=JSON.parse(before);return}const host=document.getElementById('office-photo-'+key);if(host)host.innerHTML='<img src="'+photo+'" alt="Профайлын зураг">';if(status)status.textContent='Зураг ноорогт хадгалагдлаа. Өөрчлөгдсөн профайлыг дахин шалгуулна.'}catch{if(status)status.textContent='Зураг уншиж чадсангүй. Өөр JPEG / PNG сонгоно уу.'}finally{officePhotoBusy=false;input.value=''}}
function officeRemovePhoto(key){if(officePhotoBusy||!['logo','portrait','cover'].includes(key))return;const form=document.getElementById('office-profile-form'),before=JSON.stringify(proState());officeProfileState().draft={...officeCaptureForm(form),[key]:''};if(!persistFlows()){flowState.pro=JSON.parse(before);return}render()}
function officeAdminPanel(){const p=officeProfileState(),r=adminState().officeProfileReview,status=officePublicModel('broker-local')?'published':r?.key===officeProfileKey()?r.status:p.submittedKey===officeProfileKey()?'pending':'draft';return `<section class="admin-panel office-admin-panel"><div class="admin-panel-head"><div><h2>Нийтийн профайлын хяналт</h2><p>Танилцуулга, зураг, координат, нийтэд харагдах холбоо барих мэдээлэл.</p></div>${adminBadge(status)}</div><p class="admin-note">Байгууллагын баталгаажуулалт болон профайлын зөвшөөрөл хоёулаа хүчинтэй үед л хэрэглэгчид харагдана.</p><div class="office-admin-actions"><button class="admin-primary" onclick="officeOpenProfileReview()">Профайл шалгах</button><a href="#/pro/office">PRO профайлын ноорог ${icon('arrow-up-right')}</a>${officePublicModel('broker-local')?'<a href="#/offices/broker-local">Нийтийн профайл '+icon('arrow-up-right')+'</a>':''}</div>${r?.reason?'<p class="admin-note">'+esc(r.reason)+'</p>':''}</section>`}
function officeOpenProfileReview(){const p=officeProfileState(),d=p.draft,ready=p.submittedKey===officeProfileKey(),r=adminState().officeProfileReview;modal(`<div class="admin-modal-heading"><span>НИЙТИЙН ПРОФАЙЛ</span><h2>${esc(proState().office.name)}</h2><p>Хүсэлтийн хувилбар ${p.revision||0}</p></div><div class="office-admin-preview"><div class="office-avatar">${officeAvatar({logo:d.logo})}</div><h3>${esc(d.headline||'Товч танилцуулга алга')}</h3><p>${esc(d.description||'Танилцуулга оруулаагүй')}</p><p>${esc(d.businessHours||'Ажлын цаг алга')}</p><p>Координат: ${esc(d.latitude||'—')}, ${esc(d.longitude||'—')}</p><p>Утас харуулах: ${d.showPhone?'Тийм':'Үгүй'} · Имэйл: ${d.showEmail?'Тийм':'Үгүй'}</p><div>${['portrait','cover'].filter(k=>officeAsset(d[k])).map(k=>`<img src="${d[k]}" alt="Шалгах профайлын зураг">`).join('')}</div></div>${ready?`<form onsubmit="officeSubmitProfileReview(event)"><input type="hidden" name="key" value="${esc(p.submittedKey)}">${adminSelect('Профайлын шийдвэр','status',['approved','rejected','hidden'],'approved')}${adminTextarea('Профайлын хяналтын тайлбар','reason',r?.reason||'')}<p class="admin-form-note">Зураг ашиглах эрх, танилцуулгын агуулга, оффисын координат ба ил гаргах холбоо барих мэдээллийг шалгана.</p><p class="office-form-error" role="alert"></p>${adminFormActions('Профайлын шийдвэр хадгалах')}</form>`:'<p class="notice">Одоогийн хувилбар хяналтад ирээгүй. PRO дээр мэдээллээ хадгалж хяналтад илгээнэ үү.</p>'}`);document.querySelector('.modal').classList.add('admin-modal','office-admin-review')}
function officeSubmitProfileReview(event){event.preventDefault();const f=new FormData(event.target),p=officeProfileState(),status=String(f.get('status')),reason=String(f.get('reason')||'').trim(),key=String(f.get('key'));if(!['approved','rejected','hidden'].includes(status)||key!==p.submittedKey||key!==officeProfileKey())return;if(!reason){event.target.querySelector('.office-form-error').textContent='Хяналтын тайлбар оруулна уу.';return}if(status==='approved'&&(!brokerEligible()||officeProfileErrors(p.draft).length)){event.target.querySelector('.office-form-error').textContent='Байгууллагын эрх, профайлын бүрэн мэдээллийг шалгана уу.';return}adminCommit('Нийтийн профайлын хяналт',proState().office.name,()=>adminState().officeProfileReview={status,key,reason,date:new Date().toISOString(),snapshot:officeCleanDraft(p.draft)},adminState().officeProfileReview?.status,ADMIN_LABELS[status],reason)}
